protocol TaskRepository: Sendable {
    func load() throws -> [TaskItem]
    func save(_ tasks: [TaskItem]) throws
}

struct JSONTaskRepository: TaskRepository {
    let fileURL: URL

    func load() throws -> [TaskItem] {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return [] }
        return try JSONDecoder().decode([TaskItem].self, from: Data(contentsOf: fileURL))
    }

    func save(_ tasks: [TaskItem]) throws {
        try JSONEncoder().encode(tasks).write(to: fileURL, options: .atomic)
    }
}
"}

